:root{
  box-sizing:border-box;
  padding-top:env(safe-area-inset-top,0px);
  padding-bottom:env(safe-area-inset-bottom,0px);
  color-scheme:light;
  --red:#c4161c; --black:#0a0a0a;
  --bg:#f4f4f4; --surface:#ffffff; --text:#0a0a0a; --muted:#555555; --line:#dcdcdc;
  --stage-1:#ffffff; --stage-2:#ededed; --stage-3:#d5d5d5; --quilt:rgba(10,10,10,.055);
  --worn-1:#d6d4d1; --worn-2:#bfbdb9;
  --hdr:rgba(244,244,244,.92);
  --chip-on:#0a0a0a; --on-chip-on:#ffffff;
  --lgd:block; --lgl:none; --focus:#c4161c;
  --glass:rgba(255,255,255,.82);
  --shadow:0 24px 50px -28px rgba(0,0,0,.45);
  --r-s:8px; --r-m:12px; --r-l:16px;
  --pad:clamp(18px,2.8vw,64px); --hdr-h:76px;
  --mk:#f8e1e1; --mkc:#c4161c; --hc:#b86a2a;
  --display:"IBM Plex Sans Arabic","Segoe UI",Tahoma,"Geeza Pro",sans-serif;
  --body:"IBM Plex Sans Arabic","Segoe UI",Tahoma,"Geeza Pro",sans-serif;
  --mask:url("data:image/svg+xml;base64,");
  --m-body:url("data:image/webp;base64,");
  --m-ins:url("data:image/webp;base64,");
}
:root[data-theme="dark"]{
  color-scheme:dark;
  --bg:#0a0a0a; --surface:#151515; --text:#f2f2f2; --muted:#a9a9a9; --line:#2b2b2b;
  --stage-1:#4a4a4a; --stage-2:#262626; --stage-3:#0e0e0e; --quilt:rgba(255,255,255,.055);
  --worn-1:#2f2f2f; --worn-2:#1b1b1b;
  --hdr:rgba(10,10,10,.9);
  --chip-on:#c4161c; --on-chip-on:#ffffff;
  --lgd:none; --lgl:block; --focus:#ffffff;
  --glass:rgba(20,20,20,.78);
  --shadow:0 24px 50px -28px rgba(0,0,0,.95);
  --mk:rgba(196,22,28,.22); --mkc:#ff6b70;
}
*,*::before,*::after{box-sizing:inherit}
[hidden]{display:none!important}
@property --hc{syntax:'<color>';inherits:true;initial-value:#b86a2a}
html{scroll-padding-top:calc(env(safe-area-inset-top,0px) + 88px);-webkit-text-size-adjust:100%;overflow-x:clip}
html.lock{overflow:hidden}
body{margin:0;background:var(--bg);color:var(--text);font:400 1.0625rem/1.8 var(--body);-webkit-font-smoothing:antialiased;transition:background-color .3s,color .3s}
img,svg{max-width:100%}
button,input{font:inherit;color:inherit}
button{cursor:pointer}
a{color:inherit}
h1,h2,h3{font-family:var(--display);margin:0}
:focus-visible{outline:3px solid var(--focus);outline-offset:3px;border-radius:6px}
.wrap{width:min(100% - 2 * var(--pad),1900px);margin-inline:auto}
.i{width:24px;height:24px;flex:none;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.social a:has(use[href="#i-snap"]) .i,.social a:has(use[href="#i-x"]) .i{fill:currentColor;stroke:none}

/* ---------- seat renderer (atelier) ---------- */
.b0{background-image:url(data:image/webp;base64,)}
.b1{background-image:url(data:image/webp;base64,)}
.b2{background-image:url(data:image/webp;base64,)}
.seat{position:relative;aspect-ratio:820/1219;isolation:isolate;pointer-events:none;--sheen:.55;--gloss:.12}
.seat[data-finish="matte"]{--sheen:.28;--gloss:0}
.seat[data-finish="smooth"]{--sheen:.55;--gloss:.12}
.seat[data-finish="glossy"]{--sheen:.85;--gloss:.5}
.seat > *{position:absolute;inset:0;display:block}
.seat .base{background-size:100% 100%;background-repeat:no-repeat;transition:opacity .45s}
.seat .tint{mix-blend-mode:multiply;transition:background-color .5s}
.seat .t1{background:var(--t1,#888);-webkit-mask:var(--m-body) center/100% 100% no-repeat;mask:var(--m-body) center/100% 100% no-repeat}
.seat .t2{background:var(--t2,var(--t1,#888));-webkit-mask:var(--m-ins) center/100% 100% no-repeat;mask:var(--m-ins) center/100% 100% no-repeat}
.seat .lift{background:#fff;mix-blend-mode:screen;transition:opacity .5s}
.seat .l1{opacity:var(--l1,0);-webkit-mask:var(--m-body) center/100% 100% no-repeat;mask:var(--m-body) center/100% 100% no-repeat}
.seat .l2{opacity:var(--l2,var(--l1,0));-webkit-mask:var(--m-ins) center/100% 100% no-repeat;mask:var(--m-ins) center/100% 100% no-repeat}
.seat .sheen{-webkit-mask:var(--mask) center/100% 100% no-repeat;mask:var(--mask) center/100% 100% no-repeat;mix-blend-mode:soft-light;opacity:var(--sheen);background-size:100% 100%;transition:opacity .45s}
.seat .gloss{-webkit-mask:var(--mask) center/100% 100% no-repeat;mask:var(--mask) center/100% 100% no-repeat;mix-blend-mode:screen;opacity:var(--gloss);background:linear-gradient(104deg,transparent 22%,rgba(255,255,255,.0) 30%,rgba(255,255,255,.75) 41%,rgba(255,255,255,0) 52%,transparent 60%);transition:opacity .45s}
.seat .wear{-webkit-mask:var(--mask) center/100% 100% no-repeat;mask:var(--mask) center/100% 100% no-repeat;mix-blend-mode:multiply}
.seat .wear svg{width:100%;height:100%;display:block}
.photo{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;-webkit-user-drag:none;user-select:none}
.quilt{
  background:
    linear-gradient(45deg,transparent calc(50% - 1px),var(--quilt) calc(50% - 1px),var(--quilt) calc(50% + 1px),transparent calc(50% + 1px)) 0 0/64px 64px,
    linear-gradient(-45deg,transparent calc(50% - 1px),var(--quilt) calc(50% - 1px),var(--quilt) calc(50% + 1px),transparent calc(50% + 1px)) 0 0/64px 64px,
    radial-gradient(ellipse 62% 56% at 50% 44%,var(--stage-1) 0%,var(--stage-2) 58%,var(--stage-3) 100%);
}

/* ---------- buttons ---------- */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:12px;min-height:52px;padding:0 28px;border-radius:var(--r-s);border:0;background:var(--red);color:#fff;font-weight:500;text-decoration:none;font-size:1rem;transition:transform .15s,filter .15s,background-color .2s,color .2s}
.btn:hover{filter:brightness(1.1)}
.btn:active{transform:scale(.98)}
.btn.ghost{background:transparent;color:var(--text);box-shadow:inset 0 0 0 1.5px var(--text)}
.btn.ghost:hover{background:var(--text);color:var(--bg);filter:none}
.btn.small{min-height:46px;padding:0 20px;font-size:.95rem}
.ibtn{width:48px;height:48px;flex:none;display:grid;place-items:center;border-radius:var(--r-s);border:1.5px solid var(--line);background:var(--surface);color:var(--text);padding:0;text-decoration:none;transition:border-color .2s,transform .15s}
.ibtn:hover{border-color:var(--text)}
.ibtn:disabled{opacity:.4;cursor:default}
.ibtn:active{transform:scale(.95)}

/* ---------- header: logo in the middle ---------- */
.top{position:sticky;top:env(safe-area-inset-top,0px);z-index:30;background:transparent;border-bottom:1px solid transparent;transition:background-color .4s ease,border-color .4s ease,box-shadow .4s ease}
.top.on{background:color-mix(in srgb,var(--bg) 74%,transparent);-webkit-backdrop-filter:blur(18px);backdrop-filter:blur(18px);border-bottom-color:color-mix(in srgb,var(--text) 14%,transparent)}
.bar{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:20px;min-height:var(--hdr-h)}
.side{display:flex;align-items:center;gap:6px}
.side.end{justify-content:flex-end;gap:10px}
.nav a{display:inline-flex;align-items:center;min-height:42px;padding:0 14px;border-radius:999px;text-decoration:none;font-weight:500;font-size:.94rem;color:var(--muted);transition:color .25s ease,background-color .25s ease}
.nav a:hover{color:var(--text);background:color-mix(in srgb,var(--text) 8%,transparent)}
.brand{display:block;line-height:0}
.brand img{height:34px;width:auto}
.brand .lg-d{display:var(--lgd)}
.brand .lg-l{display:var(--lgl)}
.top::after{content:"";position:absolute;right:0;left:0;bottom:-1px;height:3px;background:var(--red);transform-origin:right center;transform:scaleX(var(--sp,0));pointer-events:none}
.theme .moon{display:block}.theme .sun{display:none}
:root[data-theme="dark"] .theme .moon{display:none}
:root[data-theme="dark"] .theme .sun{display:block}
.theme.only-m{display:none}
@media (max-width:860px){
  .nav{display:none}
  .theme.only-m{display:grid}
  .theme.only-d{display:none}
  :root{--hdr-h:68px}
  .bar{direction:ltr;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);gap:10px}
  .side.start,.side.end{display:contents}
  .theme.only-m{grid-column:1;justify-self:start}
  .brand{grid-column:2;justify-self:center;min-width:0}
  .brand img{height:24px}
  .btn.small.wa{width:48px;padding:0}
  .wa span{display:none}
}

/* ---------- compare slider ---------- */
.cmp{position:relative;overflow:hidden;border-radius:var(--r-m);touch-action:pan-y;user-select:none;-webkit-user-select:none;cursor:ew-resize;--pos:50%;background:var(--worn-2)}
.cmp .pane{position:absolute;inset:0;isolation:isolate}
.cmp .pane.before{background:linear-gradient(180deg,var(--worn-1),var(--worn-2))}
.cmp .pane.after{clip-path:inset(0 calc(100% - var(--pos)) 0 0)}
.cmp .pane .seat{position:absolute;top:5%;height:90%;left:50%;transform:translateX(-50%)}
.pane::after{content:"";position:absolute;left:50%;bottom:3%;width:46%;height:4.5%;transform:translateX(-50%);background:radial-gradient(ellipse at center,rgba(0,0,0,.38),transparent 70%);z-index:-1}
.pane.has-photo::after{display:none}
.tag{position:absolute;top:18px;z-index:5;min-height:44px;padding:0 20px;border-radius:var(--r-s);border:0;font-weight:500;font-size:1rem;background:rgba(0,0,0,.78);color:#fff}
.tag.t-before{right:18px}
.tag.t-after{left:18px;background:var(--red)}
.handle{position:absolute;z-index:4;top:0;bottom:0;left:var(--pos);width:60px;margin-left:-30px;display:grid;place-items:center;outline-offset:-4px}
.handle::before{content:"";position:absolute;top:0;bottom:0;left:50%;width:2px;margin-left:-1px;background:#fff;box-shadow:0 0 0 1px rgba(0,0,0,.25)}
.grip{position:relative;width:58px;height:58px;border-radius:50%;background:var(--red);color:#fff;display:grid;place-items:center;box-shadow:0 0 0 3px #fff,0 10px 24px rgba(0,0,0,.4)}
.grip .i{width:28px;height:28px;stroke-width:2.4}
.swap-fade .pane .seat,.swap-fade .photo{opacity:0}
.pane .seat,.photo{transition:opacity .25s}

/* ---------- highlighter text (brand style) ---------- */
mark{position:relative;display:inline-block;isolation:isolate;background:none;color:var(--mkc);padding:0 .34em .1em;white-space:nowrap}
mark::before{content:"";position:absolute;inset:0;z-index:-1;background:var(--mk);border-radius:.4em;transform:scaleX(0);transform-origin:right center;transition:transform .9s cubic-bezier(.2,.7,.2,1) var(--d,0s)}
mark.in::before,.rv.in mark::before,.in mark::before{transform:scaleX(1)}
.eyebrow{display:inline-flex;align-items:center;gap:12px;margin:0 0 22px;font-weight:600;font-size:1rem}
.bars{display:inline-flex;gap:4px}
.bars i{display:block;width:7px;height:15px;background:var(--red);transform:skewX(-24deg)}

/* ---------- scroll reveal ---------- */
.js .rv{opacity:0;transform:translateY(26px);transition:opacity .8s ease var(--d,0s),transform .8s cubic-bezier(.2,.7,.2,1) var(--d,0s)}
.js .rv.in{opacity:1;transform:none}

/* ---------- hero ---------- */
.hero{--rail:320px;position:relative;overflow:hidden;min-height:calc(100svh - var(--hdr-h));display:flex;align-items:center;padding:28px 0 40px}
.hero::before{content:"";position:absolute;inset:0;pointer-events:none;
  background:
    linear-gradient(45deg,transparent calc(50% - 1px),var(--quilt) calc(50% - 1px),var(--quilt) calc(50% + 1px),transparent calc(50% + 1px)) 0 0/96px 96px,
    linear-gradient(-45deg,transparent calc(50% - 1px),var(--quilt) calc(50% - 1px),var(--quilt) calc(50% + 1px),transparent calc(50% + 1px)) 0 0/96px 96px;
  -webkit-mask:radial-gradient(ellipse 42% 70% at 50% 50%,#000 0%,transparent 78%);mask:radial-gradient(ellipse 42% 70% at 50% 50%,#000 0%,transparent 78%)}
.hero .wrap{width:min(100% - 2 * var(--pad),1900px);position:relative}
.hero-grid{direction:ltr;display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);align-items:center;column-gap:clamp(28px,4vw,72px);min-height:calc(100svh - var(--hdr-h) - 68px)}
.hero-stage{display:contents}
.hero-balance{display:none}
.hero-play{grid-column:1;grid-row:1;justify-self:start;align-self:center}
.hero-seat{grid-column:2;grid-row:1;justify-self:center}
.hero-copy{grid-column:3;grid-row:1;justify-self:end;align-self:center;width:min(380px,100%);direction:rtl;text-align:right;will-change:transform,opacity}
[dir="ltr"] .hero-copy{direction:ltr;text-align:left}
.hero .eyebrow{margin:0 0 14px;font-size:.95rem;gap:8px}
.hero h1{font:700 clamp(1.85rem,2.6vw,2.55rem)/1.35 var(--display);margin:0 0 14px;text-wrap:balance}
.hero h1 mark{padding:0 .28em .08em;margin-top:.06em}
.hero .sub{margin:0 0 22px;color:var(--muted);font-size:1.05rem;line-height:1.6;font-weight:500;max-width:18em}
.cta{display:flex;flex-wrap:wrap;gap:12px}
.hero .cta{flex-direction:row;flex-wrap:nowrap;align-items:center;gap:10px}
.hero .cta .btn{min-height:48px;padding:0 18px;font-size:.95rem;gap:8px;white-space:nowrap}

.hero-seat{position:relative;display:grid;justify-items:center}
.hero-seat .glow{position:absolute;top:2%;left:50%;width:min(120%,780px);aspect-ratio:1;transform:translateX(-50%);border-radius:50%;background:radial-gradient(circle,color-mix(in srgb,var(--hc) 42%,transparent) 0%,color-mix(in srgb,var(--hc) 14%,transparent) 48%,transparent 70%);transition:--hc .7s ease;pointer-events:none}
.seat-holder{position:relative;height:min(90svh,980px);min-height:520px;display:grid;place-items:center;will-change:transform}
.seat-holder .seat{height:100%}
.seat-holder::after{content:"";position:absolute;left:50%;bottom:1%;width:62%;height:5%;transform:translateX(-50%);background:radial-gradient(ellipse at center,rgba(0,0,0,.4),transparent 70%);z-index:-1}
.pname{display:flex;align-items:center;gap:10px;font-weight:600;font-size:1.05rem;min-height:30px}
.pname small{color:var(--muted);font-weight:400;font-size:.95rem}
.hsws{display:flex;flex-wrap:wrap;justify-content:center;gap:6px}
.hsw{width:44px;height:44px;padding:0;border:0;background:transparent;border-radius:50%;display:grid;place-items:center;position:relative}
.hsw i{display:block;width:30px;height:30px;border-radius:50%;background:var(--c);box-shadow:inset 0 0 0 1px rgba(128,128,128,.45),inset 0 -6px 10px rgba(0,0,0,.25),inset 0 5px 8px rgba(255,255,255,.2);transition:transform .2s}
.hsw:hover i{transform:scale(1.14)}
.hsw[aria-checked="true"]::after{content:"";position:absolute;inset:2px;border-radius:50%;border:2px solid var(--text)}
.hsw[aria-checked="true"] i{transform:scale(.88)}
.seg{display:inline-flex;border:1.5px solid var(--line);border-radius:var(--r-s);overflow:hidden;background:var(--surface)}
.seg button{display:flex;align-items:center;gap:6px;min-height:44px;padding:0 14px;border:0;background:transparent;font-weight:500;font-size:.92rem;transition:background-color .2s,color .2s}
.seg button + button{border-inline-start:1px solid var(--line)}
.seg button .i{width:18px;height:18px}
.seg button[aria-pressed="true"]{background:var(--text);color:var(--bg)}

.play-pats,.play-cols{display:contents}
.hero-play{direction:rtl;width:var(--rail,320px);display:flex;flex-direction:column;align-items:stretch;gap:12px;padding:18px 16px 14px;border-radius:28px;background:color-mix(in srgb,var(--surface) 92%,transparent);border:1px solid var(--line);box-shadow:0 22px 50px rgba(0,0,0,.16);position:relative}
[dir="ltr"] .hero-play{direction:ltr}
.hero-play::before{content:"";position:absolute;right:-8px;left:auto;top:18%;bottom:18%;width:3px;border-radius:3px;background:var(--red)}
.hud-label{margin:0;width:100%;text-align:center;font-size:.72rem;font-weight:700;letter-spacing:.06em;color:var(--muted)}
.hero-play .play-cols > .hud-label{margin-top:2px;padding-top:12px;border-top:1px solid var(--line)}
.hero-play .seg{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;border:0;background:transparent;overflow:visible;width:100%}
.hero-play .seg button{flex-direction:column;justify-content:center;gap:6px;width:100%;min-height:74px;padding:10px 6px;border-radius:16px;border:1.5px solid transparent;background:var(--bg);font-size:.8rem;line-height:1.2;font-weight:600;transition:background-color .2s,color .2s,transform .2s,border-color .2s,box-shadow .2s}
.hero-play .seg button + button{border-inline-start:0}
.hero-play .seg button .i{width:22px;height:22px}
.hero-play .seg button:hover{border-color:color-mix(in srgb,var(--text) 28%,transparent)}
.hero-play .seg button[aria-pressed="true"]{background:var(--text);color:var(--bg);border-color:var(--text);transform:translateY(-1px);box-shadow:0 10px 18px rgba(0,0,0,.2)}
.hero-play .swatch-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));justify-content:stretch;gap:10px;width:100%}
.hero-play .hsws{display:contents}
.hero-play .hsw{width:100%;height:auto;aspect-ratio:1;border-radius:16px}
.hero-play .hsw i{width:62%;height:62%;border-radius:12px}
.hcustom{position:relative;width:42px;height:42px;border-radius:14px;display:grid;place-items:center;cursor:pointer;border:1.5px dashed color-mix(in srgb,var(--text) 42%,transparent);background:var(--bg)}
.hero-play .hcustom{grid-column:1 / -1;width:100%;height:44px;aspect-ratio:auto;border-radius:14px;display:flex;align-items:center;justify-content:center;gap:8px}
.hcustom input{position:absolute;inset:0;opacity:0;cursor:pointer;width:100%;height:100%}
.hcustom-face{width:24px;height:24px;border-radius:8px;background:conic-gradient(#c4161c,#e8b15a,#efe6d3,#51633f,#27406b,#c4161c);box-shadow:inset 0 0 0 1px rgba(128,128,128,.35)}
.hcustom-name{font-size:.78rem;font-weight:700}
.hcustom[aria-checked="true"]{border-style:solid;border-color:var(--red)}
.hcustom[aria-checked="true"] .hcustom-face{background:var(--pick,#c4161c)}
.hero-play .hsw[aria-checked="true"]::after{inset:0;border-radius:16px;border:2px solid var(--red)}
.hero-play .hsw[aria-checked="true"] i{animation:slot .32s cubic-bezier(.2,.8,.2,1)}
.hero-play .pname{flex-direction:column;gap:2px;width:100%;min-height:0;text-align:center;font-size:.95rem;line-height:1.4;text-wrap:balance}
.hero-play .pname small{font-size:.72rem}
.hero-play .pname .dot{width:9px;height:9px}
@keyframes slot{0%{transform:scale(.55)}55%{transform:scale(1.12)}100%{transform:scale(.9)}}
.seat .shine{-webkit-mask:var(--mask) center/100% 100% no-repeat;mask:var(--mask) center/100% 100% no-repeat;mix-blend-mode:screen;opacity:0;background:linear-gradient(104deg,transparent 32%,rgba(255,255,255,.85) 50%,transparent 68%);background-size:260% 100%;background-position:120% 0}
.seat.pulse .shine{animation:shine .95s ease-out}
@keyframes shine{0%{opacity:1;background-position:120% 0}100%{opacity:1;background-position:-30% 0}}
@media (max-width:980px){
  .hero{min-height:0;padding:22px 0 48px;align-items:flex-start}
  .hero-grid{display:flex;flex-direction:column;direction:rtl;align-items:stretch;gap:22px;min-height:0}
  [dir="ltr"] .hero-grid{direction:ltr}
  .hero-copy{width:auto;max-width:36em}
  .hero .cta{flex-direction:row;flex-wrap:wrap;align-items:center}
  .hero-seat{order:1}
  .hero-play{order:2}
  .hero h1{font-size:clamp(1.55rem,5.4vw,2rem)}
  .hero-balance{display:none}
  .hero-stage{display:flex;flex-direction:column;gap:16px;width:100%}
  .hero-play,.hero-seat{grid-column:auto;justify-self:stretch}
  .hero-play{width:min(100%,520px);flex-direction:row;flex-wrap:wrap;justify-content:center;border-radius:22px;padding:12px}
  .hero-play::before{display:none}
  .hero-play .swatch-grid{display:flex;flex-wrap:wrap;justify-content:center;gap:6px;width:auto}
  .hero-play .seg,.hero-play .hsws{display:flex;flex-direction:row;width:auto;grid-template-columns:none}
  .hero-play .pname{flex-direction:row;gap:6px}
  .seat-holder{height:min(52svh,460px);min-height:300px}
  .seg button span{display:none}
  .hero-play .seg button span{display:block}
}
@media (max-height:760px) and (min-width:981px){
  .seat-holder{height:min(68svh,680px);min-height:0}
  .hero-play .seg button{min-height:44px}
  .hero-play .hsw{width:30px;height:30px}
}

/* ---------- screens: wide, tablet, phone, vertical store ---------- */
.hero-grid,.hero-stage,.hero-copy,.hero-seat,.hero-play{min-width:0}
.seat-holder .seat{max-width:none;height:100%;width:auto}
@media (min-width:1600px){
  .seat-holder{height:min(88svh,1080px)}
  .hero-copy{width:min(440px,100%)}
  .hero h1{font-size:clamp(2.1rem,2.4vw,2.85rem)}
}
@media (max-width:1280px) and (min-width:981px){
