/* ---------- works: projects + mosaic ---------- */
.works{padding:88px 0 104px;background:var(--surface);border-block:1px solid var(--line)}
.works .sec-head{display:block;margin-bottom:22px}
.works .sec-head .eyebrow{margin-bottom:10px}
.sec-head{display:flex;flex-wrap:wrap;align-items:end;justify-content:space-between;gap:14px 40px;margin-bottom:30px}
.sec-head h2{text-wrap:balance;font:700 clamp(1.7rem,2.7vw,2.5rem)/1.6 var(--display)}
.sec-head p,.subline{margin:8px 0 0;color:var(--muted);max-width:36em;font-size:1.05rem;font-weight:500}
.filter-open{display:none;position:relative}
.filter-open.hot::after{content:"";position:absolute;top:8px;inset-inline-end:8px;width:8px;height:8px;border-radius:50%;background:var(--red)}
.filter-backdrop{position:fixed;inset:0;z-index:39;border:0;padding:0;background:rgba(0,0,0,.5);cursor:pointer}
.filter-bar{display:none}
.filter-drawer{display:block}
.filters{display:flex;flex-direction:row;flex-wrap:nowrap;align-items:center;gap:6px 16px;margin:0 0 28px;padding:8px 10px;overflow-x:auto;border:1px solid var(--line);border-radius:22px;background:color-mix(in srgb,var(--bg) 62%,var(--surface));scrollbar-width:none}
.filters::-webkit-scrollbar{display:none}
.fgroup{display:flex;align-items:center;gap:8px;min-width:0;flex:none}
.fgroup > b{flex:none;font-weight:700;color:var(--muted);font-size:.68rem;letter-spacing:.04em}
.chips{display:flex;flex-wrap:nowrap;gap:4px;overflow:visible;padding:2px;margin:0}
.chip{flex:none;display:inline-flex;align-items:center;gap:5px;min-height:32px;padding:0 10px;border-radius:999px;border:1px solid transparent;background:transparent;font-weight:600;font-size:.78rem;transition:background-color .2s,color .2s,border-color .2s}
.chip small{display:inline-grid;place-items:center;min-width:16px;height:16px;padding:0 4px;border-radius:999px;background:color-mix(in srgb,currentColor 14%,transparent);font-size:.62rem;font-weight:700;opacity:1}
.chip[aria-pressed="true"]{background:var(--text);color:var(--bg)}
.chip:not([aria-pressed="true"]):hover{background:color-mix(in srgb,var(--text) 7%,transparent)}
.chip.brand{min-height:32px;padding-inline:6px 10px;font-size:.78rem;background:color-mix(in srgb,var(--text) 5%,transparent)}
.blogo{height:26px;width:auto;max-width:72px;object-fit:contain}
.chip .blogo{height:16px;max-width:42px}
.blogo.mono,.pbrand.mono{display:inline-block;background:currentColor;aspect-ratio:var(--ar,1);-webkit-mask:var(--logo) center/contain no-repeat;mask:var(--logo) center/contain no-repeat;-webkit-mask-mode:alpha;mask-mode:alpha}
.bmark{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:var(--text);color:var(--bg);font-size:.85rem;font-weight:700}
.pbrand{height:32px;width:auto;max-width:88px;object-fit:contain}
.studio-result{display:flex;flex-direction:column;gap:12px;min-height:0}
.studio-result[hidden]{display:none!important}
.studio-result .eyebrow{margin-bottom:0}
.studio-result h2{font:700 clamp(1.45rem,2vw,1.9rem)/1.35 var(--display);margin:0}
.studio-result .lead{margin:0;color:var(--muted);font-size:.98rem}
.finale-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:6px 0;align-content:start}
.fcard{display:flex;flex-direction:column;align-items:flex-start;gap:8px;min-width:0;padding:12px;border-radius:16px;background:color-mix(in srgb,var(--bg) 62%,transparent);border:1px solid color-mix(in srgb,var(--text) 12%,transparent);-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px)}
.fswatch{width:100%;height:36px;border-radius:12px;box-shadow:inset 0 0 0 1px rgba(255,255,255,.28),0 8px 18px rgba(0,0,0,.18)}
.fcopy{display:flex;flex-direction:column;gap:2px;min-width:0}
.fcopy span{color:var(--muted);font-size:.78rem;line-height:1.35}
.fcopy b{font-size:.95rem;font-weight:700;line-height:1.35}
.fcard em{margin:0;font-style:normal;font-size:.72rem;font-weight:700;color:var(--red)}
.result-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:4px}

#gallery{margin-top:34px;display:grid;gap:clamp(48px,6vw,88px);transition:opacity .2s,transform .2s}
#gallery.out{opacity:0;transform:translateY(10px)}
.phead{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:14px 28px;margin-bottom:16px}
.phead h3{font:700 clamp(1.4rem,2.1vw,1.9rem)/1.5 var(--display);display:flex;align-items:center;gap:14px}
.phead h3 b{color:var(--red);font-weight:700}
.phead .bars i{height:22px;width:8px}
.phead p{margin:6px 0 0;color:var(--muted);max-width:62ch;font-size:1rem}
.pm{display:flex;align-items:center;gap:16px;color:var(--muted);font-size:.98rem}
.bento{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}
.tile{position:relative;display:flex;flex-direction:column;grid-column:auto;min-width:0;padding:0;border:1px solid var(--line);border-radius:20px;background:var(--bg);overflow:hidden;text-align:start;transition:transform .25s,box-shadow .25s,border-color .25s}
.tile.lead{grid-column:auto}
.tile:hover,.tile:focus-visible{transform:translateY(-4px);box-shadow:var(--shadow);border-color:var(--text)}
.mini{position:relative;flex:1;min-height:340px;aspect-ratio:4/5;display:block;overflow:hidden;--pos:50%;background:#111}
.tile.lead .mini{min-height:340px}
.mini .photo{object-fit:contain}
.mini .pane{position:absolute;inset:0;display:block;isolation:isolate}
.mini .pane.after{clip-path:inset(0 calc(100% - var(--pos)) 0 0)}
.mini:not(.live) .pane.after{transition:clip-path .5s cubic-bezier(.2,.7,.2,1)}
.mini .div{position:absolute;top:0;bottom:0;left:var(--pos);width:2px;margin-left:-1px;background:#fff;box-shadow:0 0 0 1px rgba(0,0,0,.35);opacity:1;z-index:3}
.mini .div::after{content:"";position:absolute;top:50%;left:50%;width:28px;height:28px;margin:-14px 0 0 -14px;border-radius:50%;background:var(--red);box-shadow:0 0 0 3px #fff}
.mini .mlb{position:absolute;top:46%;z-index:4;padding:0 10px;min-height:28px;display:inline-flex;align-items:center;border-radius:6px;background:color-mix(in srgb,#0a0a0a 55%,transparent);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);color:#fff;font-size:.82rem;font-weight:500;opacity:1}
.mini .mlb.b{right:12px}.mini .mlb.a{left:12px;background:var(--red)}
.tile .kind{position:absolute;top:14px;right:14px;z-index:5;display:inline-flex;align-items:center;min-height:32px;padding:0 12px;border-radius:999px;background:color-mix(in srgb,#0a0a0a 42%,transparent);-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px);border:1px solid color-mix(in srgb,#fff 18%,transparent);color:#fff;font-size:.9rem;font-weight:500}
.tile .cmpico{position:absolute;top:12px;left:12px;z-index:5;width:38px;height:38px;border-radius:var(--r-s);display:grid;place-items:center;background:var(--surface);color:var(--text);box-shadow:0 2px 10px rgba(0,0,0,.25);transition:background-color .2s,color .2s}
.tile:hover .cmpico{background:var(--red);color:#fff}
.tile .cmpico .i{width:20px;height:20px}
.tile .meta{position:absolute;z-index:6;inset-inline:10px;bottom:10px;display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px 14px;border:1px solid color-mix(in srgb,#fff 16%,transparent);border-radius:16px;background:color-mix(in srgb,var(--bg) 58%,transparent);-webkit-backdrop-filter:blur(16px);backdrop-filter:blur(16px);color:var(--text)}
.tile .nm b{display:block;font-weight:600;font-size:1.02rem;line-height:1.5}
.tile .nm small{color:var(--muted);font-size:.9rem}
.dot{width:22px;height:22px;border-radius:50%;flex:none;box-shadow:inset 0 0 0 1px rgba(255,255,255,.35),0 0 0 1px rgba(0,0,0,.25)}
.empty{text-align:center;color:var(--muted);padding:40px 0}
@media (max-width:980px){.bento{grid-template-columns:1fr 1fr;gap:12px}.tile,.tile.lead{grid-column:auto}.mini,.tile.lead .mini{min-height:200px}.mini .mlb{opacity:1;transform:none}}
@media (max-width:480px){.tile .meta{padding:10px 12px}.tile .nm b{font-size:1rem}.tile .kind{top:10px;right:10px;font-size:.82rem}.tile .cmpico{top:8px;left:8px;width:34px;height:34px}.works{padding:72px 0 80px}.pm{width:100%;justify-content:space-between}}

/* ---------- viewer (before / after lightbox) ---------- */
:root{--vbg:#e6e6e6}
:root[data-theme="dark"]{--vbg:#0c0c0c}
.look{background:var(--surface);color:var(--text);min-height:calc(100svh - var(--hdr-h))}
.look:not([hidden]){display:grid;grid-template-columns:minmax(0,1fr) clamp(340px,28vw,420px)}
.look .vd-stage{min-height:calc(100svh - var(--hdr-h))}
.vd-stage{position:relative;min-width:0;min-height:0;background:var(--vbg);overflow:hidden}
.vd-stage:fullscreen{background:#0c0c0c}
.vd-canvas{position:absolute;inset:0;container-type:size;display:grid;place-items:center;touch-action:pan-y;padding:66px 14px 40px}
.vd-zoom{position:relative;transform-origin:var(--zx,50%) var(--zy,50%);transform:scale(var(--z,1));transition:transform .45s cubic-bezier(.2,.7,.2,1)}
.vd-canvas.moving .vd-zoom{transition:transform .08s linear}
.vd-frames{position:relative;--pos:50%;width:min(100cqw,calc(100cqh * .75));aspect-ratio:3/4;border-radius:10px;overflow:hidden;box-shadow:0 18px 50px -20px rgba(0,0,0,.55);user-select:none;-webkit-user-select:none;background:#222}
.vd-canvas[data-mode="side"] .vd-frames{display:grid;grid-template-columns:1fr 1fr;gap:3px;width:min(100cqw,calc(100cqh * 1.5));aspect-ratio:3/2;background:var(--vbg);box-shadow:none;overflow:visible}
.vfig{position:absolute;inset:0;margin:0;overflow:hidden}
.vfig img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;-webkit-user-drag:none;user-select:none;transition:opacity .25s}
.vd-frames.swap .vfig img{opacity:0}
.vfig figcaption{position:absolute;bottom:16px;z-index:3;min-height:36px;padding:0 14px;display:inline-flex;align-items:center;border-radius:6px;background:rgba(0,0,0,.78);color:#fff;font-weight:500;font-size:.95rem;transition:opacity .25s}
.vfig.vfb figcaption{right:16px}.vfig.vfa figcaption{left:16px;background:var(--red)}
.vd-canvas[data-mode="slide"] .vfig.vfa{clip-path:inset(0 calc(100% - var(--pos)) 0 0)}
.vd-canvas[data-mode="side"] .vfig{position:relative;inset:auto;border-radius:10px}
.vd-canvas[data-mode="side"] .vh{display:none}
.vd-canvas[data-mode="flip"] .vfig.vfa{opacity:0;transition:opacity .35s}
.vd-canvas[data-mode="flip"][data-flip="after"] .vfig.vfa{opacity:1}
.vd-canvas[data-mode="flip"] .vh{display:none}
.vh{position:absolute;z-index:4;top:0;bottom:0;left:var(--pos);width:64px;margin-left:-32px;display:grid;place-items:center;cursor:ew-resize;touch-action:none;outline-offset:-4px}
.vh::before{content:"";position:absolute;top:0;bottom:0;left:50%;width:2px;margin-left:-1px;background:#fff;box-shadow:0 0 0 1px rgba(0,0,0,.25)}
.vd-canvas.zoomed{cursor:zoom-out}
.vd-zoom .grip{transform:scale(calc(1 / var(--z,1)));transition:transform .45s cubic-bezier(.2,.7,.2,1)}
.vd-zoom .vfig figcaption{transform:scale(calc(1 / var(--z,1)));transform-origin:center}
.vd-bar{position:absolute;z-index:6;top:14px;right:14px;left:14px;display:flex;justify-content:space-between;align-items:center;gap:10px;pointer-events:none}
.vd-bar > *{pointer-events:auto}
.vd-bar .seg{background:var(--glass);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px)}
.vd-bar .seg button{min-height:42px;padding:0 16px;font-size:.92rem}
.vd-bar .seg button[aria-pressed="true"]{background:var(--text);color:var(--bg)}
.vd-act{display:flex;gap:8px}
.vd-bar .seg .sh{display:none}
.vd-act .ibtn{background:var(--glass);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);width:44px;height:44px}
.vd-act .ibtn[aria-pressed="true"]{background:var(--text);color:var(--bg);border-color:var(--text)}
.vd-nav{position:absolute;z-index:6;top:50%;margin-top:-24px;width:48px;height:48px;border-radius:50%;border:0;background:rgba(20,20,20,.62);color:#fff;display:grid;place-items:center;-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);transition:background-color .2s,transform .15s}
.vd-nav:hover{background:var(--red)}
.vd-nav.p{right:14px}.vd-nav.n{left:14px}
.vd-nav[hidden]{display:none}
.vd-hint{position:absolute;z-index:5;bottom:14px;right:0;left:0;text-align:center;color:var(--muted);font-size:.88rem;pointer-events:none}
.vd-state{position:absolute;z-index:5;bottom:44px;left:50%;transform:translateX(-50%);padding:0 18px;min-height:40px;display:none;align-items:center;border-radius:6px;background:rgba(0,0,0,.78);color:#fff;font-weight:600}
.vd-canvas[data-mode="flip"] ~ .vd-state{display:inline-flex}
.vd-side{position:relative;display:flex;flex-direction:column;gap:20px;padding:34px 30px 24px;overflow:auto;min-width:0;border-inline-start:1px solid var(--line)}
.vd-side .x{position:absolute;top:14px;inset-inline-end:14px;z-index:2}
.vd-brand{margin:0;display:flex;align-items:center;gap:10px;color:var(--red);font-weight:700;font-size:1.05rem}
.vd-side h3{font:700 1.7rem/1.45 var(--display);margin:2px 0 0}
.vd-story{margin:8px 0 0;color:var(--muted);font-size:.98rem;line-height:1.85}
.vd-sec h4{display:flex;align-items:baseline;gap:8px;font:700 1rem/1.4 var(--display);margin:0 0 10px}
.vd-sec h4 small{color:var(--muted);font-weight:400;font-size:.9rem}
.athumbs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
.ath{position:relative;padding:0;border:2px solid transparent;border-radius:8px;overflow:hidden;aspect-ratio:3/4;background:#222;transition:border-color .2s,transform .15s}
.ath img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.ath .tb{clip-path:polygon(58% 0,100% 0,100% 100%,42% 100%)}
.ath i{position:absolute;top:-10%;bottom:-10%;left:50%;width:2px;background:#fff;transform:rotate(6.8deg);box-shadow:0 0 0 1px rgba(0,0,0,.2)}
.ath:hover{transform:translateY(-2px)}
.ath[aria-current="true"]{border-color:var(--red)}
.ath span{position:absolute;right:0;left:0;bottom:0;padding:14px 4px 4px;font-size:.72rem;line-height:1.25;color:#fff;text-align:center;background:linear-gradient(to top,rgba(0,0,0,.78),transparent)}
.vd-sec p{margin:0 0 8px;line-height:1.85}
.vd-sec dl{margin:0}
.vd-side .dlg-actions{display:grid;gap:10px}
.vd-side .pager{margin-top:auto;padding-top:6px}
.row{display:grid;grid-template-columns:90px 1fr;gap:14px;padding:12px 0;border-top:1px solid var(--line)}
.row dt{color:var(--muted);font-size:.95rem}
.row dd{margin:0;display:flex;align-items:center;gap:10px;font-weight:500;line-height:1.7}
.pager{display:flex;align-items:center;justify-content:space-between;gap:10px}
.pager span{color:var(--muted);font-size:.95rem;white-space:nowrap}
@media (max-width:900px){
