/* ---------- studio: step-by-step interior configurator ---------- */
.vb-A{background-image:url(data:image/webp;base64,)}
.vb-B{background-image:url(data:image/webp;base64,)}
.mk-A-seats{-webkit-mask:url(data:image/webp;base64,) center/100% 100% no-repeat;mask:url(data:image/webp;base64,) center/100% 100% no-repeat}
.mk-A-heads{-webkit-mask:url(data:image/webp;base64,) center/100% 100% no-repeat;mask:url(data:image/webp;base64,) center/100% 100% no-repeat}
.mk-A-doors{-webkit-mask:url(data:image/webp;base64,) center/100% 100% no-repeat;mask:url(data:image/webp;base64,) center/100% 100% no-repeat}
.mk-A-arm{-webkit-mask:url(data:image/webp;base64,) center/100% 100% no-repeat;mask:url(data:image/webp;base64,) center/100% 100% no-repeat}
.mk-A-roof{-webkit-mask:url(data:image/webp;base64,) center/100% 100% no-repeat;mask:url(data:image/webp;base64,) center/100% 100% no-repeat}
.mk-A-all{-webkit-mask:url(data:image/webp;base64,) center/100% 100% no-repeat;mask:url(data:image/webp;base64,) center/100% 100% no-repeat}
.mk-B-wheel{-webkit-mask:url(data:image/webp;base64,) center/100% 100% no-repeat;mask:url(data:image/webp;base64,) center/100% 100% no-repeat}
.mk-B-thread{-webkit-mask:url(data:image/webp;base64,) center/100% 100% no-repeat;mask:url(data:image/webp;base64,) center/100% 100% no-repeat}
.mk-B-seatB{-webkit-mask:url(data:image/webp;base64,) center/100% 100% no-repeat;mask:url(data:image/webp;base64,) center/100% 100% no-repeat}
.mk-B-all{-webkit-mask:url(data:image/webp;base64,) center/100% 100% no-repeat;mask:url(data:image/webp;base64,) center/100% 100% no-repeat}
.studio{padding:26px 0 34px;border-top:1px solid var(--line);background:var(--bg)}
.studio-top{display:flex;flex-wrap:wrap;align-items:end;justify-content:space-between;gap:6px 32px;margin-bottom:14px}
.studio-top h2{font:700 clamp(1.45rem,2.2vw,2.05rem)/1.6 var(--display)}
.studio-top p{margin:0;color:var(--muted);font-size:1rem}
.studio-grid{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(400px,.7fr);gap:clamp(24px,3.6vw,72px);align-items:stretch;height:clamp(560px,calc(100svh - var(--hdr-h) - 124px),900px)}
.viewer{position:relative;min-width:0;height:100%;aspect-ratio:3/4;max-width:100%;justify-self:center;border-radius:0;overflow:hidden;box-shadow:none;border:0;display:grid;place-items:center;background:none}
.vframe{position:relative;height:100%;aspect-ratio:3/4;max-width:100%;overflow:hidden;background:#111}
.vw{position:absolute;inset:0;isolation:isolate;opacity:0;pointer-events:none;transition:opacity .55s}
.vw.on{opacity:1;pointer-events:auto}
.vw > i{position:absolute;inset:0;display:block;pointer-events:none}
.vbase{background-size:100% 100%;background-repeat:no-repeat}
.vt{mix-blend-mode:multiply;background:var(--c,#888);transition:background-color .55s}
.vl{mix-blend-mode:screen;background:#fff;opacity:var(--a,0);transition:opacity .55s}
.vf{mix-blend-mode:screen;background:#fff;opacity:0}
.vf.go{animation:vflash 1s ease-out}
@keyframes vflash{0%{opacity:0}18%{opacity:.62}100%{opacity:0}}
.vsheen{mix-blend-mode:soft-light;opacity:.2;background-size:100% 100%;background-repeat:no-repeat}
.hot{position:absolute;z-index:5;width:56px;height:56px;margin:-28px 0 0 -28px;padding:0;border:0;background:transparent;display:grid;place-items:center;cursor:pointer}
.hot .hping{position:absolute;width:18px;height:18px;border-radius:50%;border:2px solid #fff;animation:ping 1.8s ease-out infinite;pointer-events:none}
.hot .hdot{position:relative;width:18px;height:18px;border-radius:50%;background:#fff;box-shadow:0 0 0 2px rgba(0,0,0,.55),0 0 0 7px rgba(255,255,255,.22);transition:transform .2s,background-color .2s,box-shadow .2s}
.hot .htag{position:absolute;top:50%;inset-inline-start:calc(100% - 6px);transform:translateY(-50%);padding:5px 10px;border-radius:999px;background:rgba(8,8,8,.88);color:#fff;font:600 .78rem/1.2 var(--body);white-space:nowrap;opacity:0;pointer-events:none;box-shadow:0 8px 20px rgba(0,0,0,.28);transition:opacity .2s}
.hot:hover .hdot,.hot:focus-visible .hdot{transform:scale(1.18)}
.hot:hover .htag,.hot:focus-visible .htag,.hot[aria-current="true"] .htag,.viewer.touch .hot .htag{opacity:1}
.hot[aria-current="true"]{z-index:6}
.hot[aria-current="true"] .hdot{background:var(--red);box-shadow:0 0 0 3px #fff,0 0 0 8px color-mix(in srgb,var(--red) 55%,transparent);transform:scale(1.12)}
.hot[aria-current="true"] .hping{border-color:var(--red)}
.hot[aria-current="true"] .htag{background:var(--red)}
@keyframes ping{from{transform:scale(1);opacity:.85}to{transform:scale(2.8);opacity:0}}
.vpre{position:absolute;top:14px;right:14px;left:14px;z-index:4;display:flex;flex-wrap:wrap;gap:8px;align-items:center;pointer-events:none}
.vpre > *{pointer-events:auto}
.vpre b{font-weight:600;font-size:.95rem;color:var(--text);margin-inline-end:4px}
.vpre button{min-height:40px;padding:0 14px;border-radius:var(--r-s);border:1.5px solid var(--line);background:var(--glass);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);font-weight:500;font-size:.92rem;transition:border-color .2s,background-color .2s,color .2s}
.vpre button:hover{border-color:var(--text)}
.vpre button[aria-pressed="true"]{background:var(--text);color:var(--bg);border-color:var(--text)}
.vtabs{position:absolute;bottom:14px;left:50%;transform:translateX(-50%);z-index:4;display:inline-flex;border:1.5px solid var(--line);border-radius:var(--r-s);overflow:hidden;background:var(--glass);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px)}
.vtabs button{min-height:42px;padding:0 18px;border:0;background:transparent;font-weight:500;font-size:.92rem;transition:background-color .2s,color .2s}
.vtabs button + button{border-inline-start:1px solid var(--line)}
.vtabs button[aria-pressed="true"]{background:var(--text);color:var(--bg)}
.fsbtn{position:absolute;bottom:14px;left:14px;z-index:4;width:44px;height:44px;border-radius:50%;border:0;background:rgba(80,80,80,.72);color:#fff;display:grid;place-items:center}
.fsbtn:hover{background:rgba(40,40,40,.9)}
.viewer:fullscreen{border-radius:0;background:#0a0a0a}
.vpanel{min-width:0;display:flex;flex-direction:column;overflow:auto;padding-inline-end:4px}
.opt-head{display:flex;align-items:stretch;justify-content:space-between;gap:20px;padding-bottom:16px;border-bottom:1.5px solid var(--text)}
.opt-head h3{font:700 clamp(1.5rem,2.2vw,2.1rem)/1.45 var(--display);margin:0;align-self:center}
.oprice{flex:none;align-self:center;padding-inline-start:20px;border-inline-start:1.5px solid var(--line);font:700 1.15rem/1.4 var(--display);white-space:nowrap}
.odesc{margin:16px 0 0;color:var(--muted);font-size:1.02rem;line-height:1.9;min-height:3.8em}
.stephead{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:10px;margin-top:auto;padding-top:18px}
.stephead h2{font:700 clamp(1.3rem,1.9vw,1.75rem)/1.4 var(--display);text-align:center}
.stephead small{display:block;text-align:center;color:var(--muted);font-size:.95rem;margin-top:2px}
.stephead small b{color:var(--text);font-weight:600}
.snav{display:inline-flex;align-items:center;gap:6px;min-height:44px;padding:0 6px;border:0;background:transparent;font-weight:500;font-size:1rem;color:var(--text)}
.snav:disabled{opacity:.35;cursor:default}
.snav.back{justify-self:start}.snav.next{justify-self:end}
.snav:not(:disabled):hover{color:var(--red)}
.sline{height:1.5px;background:var(--line);margin:14px 0 16px}
.matchrow{display:flex;align-items:center;gap:10px;margin-bottom:12px}
.matchbtn{display:inline-flex;align-items:center;gap:10px;min-height:42px;padding:0 14px;border-radius:var(--r-s);border:1.5px solid var(--line);background:var(--surface);font-weight:500;font-size:.95rem;transition:border-color .2s,background-color .2s,color .2s}
.matchbtn .box{width:18px;height:18px;border-radius:4px;border:1.5px solid currentColor;display:grid;place-items:center}
.matchbtn[aria-pressed="true"]{background:var(--text);color:var(--bg);border-color:var(--text)}
.matchbtn[aria-pressed="true"] .box::after{content:"";width:9px;height:5px;border:2px solid currentColor;border-top:0;border-right:0;transform:rotate(-45deg) translate(1px,-1px)}
.swgrid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px 8px}
.swb{display:grid;justify-items:center;gap:8px;padding:2px 0 0;border:0;background:transparent;font-size:.92rem;line-height:1.4;color:var(--muted);text-align:center;min-height:44px}
.ball{position:relative;display:block;width:clamp(52px,4.6vw,68px);aspect-ratio:1;border-radius:50%;background:
  radial-gradient(circle at 30% 26%,rgba(255,255,255,.72) 0,rgba(255,255,255,0) 30%),
  radial-gradient(circle at 70% 78%,rgba(0,0,0,.34) 0,rgba(0,0,0,0) 55%),var(--c);
  box-shadow:inset 0 0 0 1px rgba(128,128,128,.35),0 6px 12px -6px rgba(0,0,0,.5);transition:transform .2s}
.swb:hover .ball{transform:scale(1.07)}
.swb[aria-checked="true"]{color:var(--text);font-weight:600}
.swb[aria-checked="true"] .ball::after{content:"";position:absolute;inset:-5px;border-radius:50%;border:2px solid var(--text)}
.summary{display:grid;gap:0}
.srow{display:grid;grid-template-columns:1fr auto;align-items:center;gap:12px;padding:8px 0;border-bottom:1px solid var(--line)}
.srow:first-child{border-top:1px solid var(--line)}
.srow span{color:var(--muted);font-size:.98rem}
.srow b{display:inline-flex;align-items:center;gap:10px;font-weight:600;font-size:1rem}
.srow .dot{width:20px;height:20px}
.sactions{display:flex;flex-wrap:wrap;gap:10px;margin-top:16px}
.sactions .btn{flex:1 1 200px}
@media (max-width:1060px){
  .studio{padding:16px 0 30px}
  .studio-grid{grid-template-columns:1fr;height:auto;gap:0}
  .viewer{position:sticky;top:calc(env(safe-area-inset-top,0px) + var(--hdr-h));z-index:6;height:min(46svh,420px);aspect-ratio:auto;max-width:none;justify-self:stretch;margin-inline:calc(var(--pad) * -1);border-radius:0;background:var(--bg)}
  .vpre{top:8px;right:10px;left:10px;flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none}.vpre::-webkit-scrollbar{display:none}
