/* ---------- footer ---------- */
.foot{background:var(--bg);color:var(--text);border-top:1px solid color-mix(in srgb,var(--text) 10%,transparent);padding:40px 0 28px;transition:background-color .4s ease,color .4s ease,border-color .4s ease}
