/* ---------- language switcher ---------- */
.lang{position:relative;display:inline-flex;padding:3px;border:1.5px solid var(--line);border-radius:999px;background:var(--surface)}
.lang::before{content:"";position:absolute;top:3px;bottom:3px;width:calc(50% - 3px);border-radius:999px;background:var(--text);inset-inline-start:3px;transition:inset-inline-start .38s cubic-bezier(.2,.8,.2,1),background-color .35s ease}
