[dir="ltr"] .hero::before{-webkit-mask:radial-gradient(ellipse 50% 85% at 76% 50%,#000 0%,transparent 78%);mask:radial-gradient(ellipse 50% 85% at 76% 50%,#000 0%,transparent 78%)}
