[dir="ltr"] .vd-canvas:not([data-mode="slide"]) .vfig.vfb figcaption{right:auto;left:16px}
[dir="ltr"] .vd-canvas:not([data-mode="slide"]) .vfig.vfa figcaption{left:auto;right:16px}
